export interface InterviewApplicant {
    id: number;
    name: string;
    career_job_id?: number;
    level?: string | null;
    work_type?: string | null;
    job?: {
        id: number;
        title?: string | null;
    } | null;
}

/** Stored in `career_interviews.evaluation` — aligned with backend `UpdateCareerInterviewRequest` */
export interface InterviewEvaluationScores {
    technical_skills?: number;
    soft_skills?: number;
    question_answers?: number;
    manager_impression?: number;
    practical_result?: number;
}

/** Matches API `career_interviews` rows with nested applicant + job */
export interface Interview {
    id: number;
    career_applicant_id?: number;
    status?: string | null;
    notes?: string | null;
    evaluation?: InterviewEvaluationScores | null;
    scheduled_at?: string | null;
    created_at: string;
    updated_at: string;
    applicant?: InterviewApplicant | null;
    /** Legacy mock fields — optional */
    name?: string;
    description?: string;
    department?: {
        id: number;
        name: string;
    };
    experience_years?: number;
    target_number?: number;
    applicants_number?: number;
    refreshTable?: () => void;
}

export function interviewApplicantName(i: Interview | null | undefined): string {
    if (!i) return '';
    const n = i.applicant?.name?.trim() || i.name?.trim();
    return n || '—';
}

export function interviewJobTitle(i: Interview | null | undefined): string {
    if (!i) return '';
    const t = i.applicant?.job?.title?.trim() || i.description?.trim() || i.department?.name?.trim();
    return t || '—';
}

export function interviewCalendarIso(i: Interview | null | undefined): string | undefined {
    if (!i) return undefined;
    return i.scheduled_at || i.created_at;
}

/** Map list/show API rows to legacy `name` / `description` used by cards */
export function normalizeInterviewFromApi(row: Interview): Interview {
    return {
        ...row,
        name: row.applicant?.name ?? row.name ?? '',
        description: row.applicant?.job?.title ?? row.description ?? '',
    };
}

export interface interviewsStats {
    total_jobs: number;
    total_applicants: number;
}
