import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Interview, normalizeInterviewFromApi } from '../../types/interview.types';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import EyeIcon from '@/components/icons/marketing/EyeIcon';
import { useEffect, useMemo, useState } from 'react';
import InterviewRejection from './InterviewRejection';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';
import {
    INTERVIEW_EVALUATION_CRITERIA,
    averageEvaluationPercent,
} from '../../constants/interviewEvaluation';

interface InterviewEvaluationProps {
    interview: Interview | null;
    openEvaluationDialog: boolean;
    setopenEvaluationDialog: (open: boolean) => void;
    /** Current page rows — used for “next interview” navigation */
    allInterviews?: Interview[];
    onSelectInterview?: (interview: Interview | null) => void;
}

export default function InterviewEvaluation({
    interview,
    openEvaluationDialog,
    setopenEvaluationDialog,
    allInterviews,
    onSelectInterview,
}: InterviewEvaluationProps) {
    const [openRejectDialog, setOpenRejectDialog] = useState(false);
    const [detail, setDetail] = useState<Interview | null>(null);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (!openEvaluationDialog || !interview?.id) {
            setDetail(null);
            return;
        }

        let cancelled = false;

        const load = async () => {
            setLoading(true);
            try {
                const res = await apiGet({
                    endpoint: `${endpoints.interview.show}${interview.id}`,
                });
                const payload = res.data?.data;
                if (!cancelled) {
                    setDetail(payload ?? null);
                }
            } catch {
                if (!cancelled) {
                    setDetail(null);
                    toast.error('تعذر تحميل بيانات المقابلة');
                }
            } finally {
                if (!cancelled) {
                    setLoading(false);
                }
            }
        };

        void load();

        return () => {
            cancelled = true;
        };
    }, [openEvaluationDialog, interview?.id]);

    const display = detail ?? interview;

    const criteriaRows = useMemo(() => {
        const ev = (display?.evaluation ?? {}) as Record<string, unknown>;
        return INTERVIEW_EVALUATION_CRITERIA.map(({ key, label }) => {
            const raw = ev[key];
            const value = typeof raw === 'number' && !Number.isNaN(raw) ? raw : 0;
            return { key, label, value };
        });
    }, [display?.evaluation]);

    const overallPercent = useMemo(
        () => averageEvaluationPercent(display?.evaluation ?? undefined),
        [display?.evaluation],
    );

    const notesText = display?.notes?.trim() ?? '';

    const handleNextInterview = () => {
        if (!interview?.id || !allInterviews?.length) {
            setopenEvaluationDialog(false);
            return;
        }
        const idx = allInterviews.findIndex((i) => i.id === interview.id);
        const next = idx >= 0 && idx < allInterviews.length - 1 ? allInterviews[idx + 1] : null;
        if (next) {
            onSelectInterview?.(next);
        } else {
            setopenEvaluationDialog(false);
        }
    };

    return (
        <div className="">
            <Dialog open={openEvaluationDialog} onOpenChange={setopenEvaluationDialog}>
                <DialogContent
                    dir="rtl"
                    showCloseButton={false}
                    className="max-w-[750px] rounded-xl border border-[#E8E7EA] bg-white-blue-50 p-5 sm:p-6 max-h-[90vh] overflow-y-auto"
                >
                    <DialogHeader className="space-y-2">
                        <DialogTitle className="text-right text-[20px] font-semibold text-[#205295]">
                            <div className="flex items-center gap-2">
                                <EyeIcon width="24" height="24" />
                                تقييم المتقدم
                            </div>
                        </DialogTitle>
                        <div className="w-full border-b border-[#E8E7EA]" />
                    </DialogHeader>

                    {loading ? (
                        <div className="mt-6 py-12 text-center text-sm text-[#625E74]">جاري التحميل...</div>
                    ) : (
                        <>
                            <div className="mt-2 rounded-xl border border-[#E5E7EB] bg-white p-3">
                                <div className="flex items-start justify-between gap-3">
                                    <div className="text-right">
                                        <h3 className="text-sm font-semibold text-primery-blue-900">
                                            {display?.applicant?.name ?? display?.name ?? ''}
                                        </h3>
                                        <p className="text-xs text-[#625E74]">
                                            {display?.applicant?.job?.title ?? display?.description ?? ''}
                                        </p>
                                        {(display?.applicant?.level || display?.applicant?.work_type) && (
                                            <p className="text-xs text-[#625E74]">
                                                {[display?.applicant?.level, display?.applicant?.work_type]
                                                    .filter(Boolean)
                                                    .join(' · ')}
                                            </p>
                                        )}
                                    </div>
                                    <span className="rounded-md bg-[#EDF8F2] px-2 py-0.5 text-[11px] text-[#1D9D62]">
                                        مقابلة
                                    </span>
                                </div>
                                <div className="mt-3">
                                    <div className="mb-1 flex items-center justify-between text-[11px] text-[#625E74]">
                                        <span>{overallPercent}%</span>
                                        <span>التقييم</span>
                                    </div>
                                    <div className="h-1.5 w-full rounded-full bg-[#E5E7EB]">
                                        <div
                                            className="h-full rounded-full bg-[#22C55E] transition-all"
                                            style={{ width: `${Math.min(100, Math.max(0, overallPercent))}%` }}
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="mt-3 flex w-full flex-row gap-3">
                                <div className="mt-3 w-[60%] space-y-1 rounded-xl border border-[#E5E7EB] p-3">
                                    <p className="text-sm font-semibold text-primery-blue-900">
                                        {display?.applicant?.name ?? display?.name ?? '-'}
                                    </p>
                                    <p className="text-sm font-semibold text-primery-blue-900">
                                        {display?.applicant?.job?.title ?? display?.description ?? '-'}
                                    </p>
                                </div>

                                <div className="mt-4 w-full rounded-xl border border-[#E5E7EB] bg-white p-3">
                                    <p className="mb-3 text-right text-sm font-semibold text-[#205295]">التقييم</p>
                                    <div className="space-y-3">
                                        {criteriaRows.map((item) => (
                                            <div key={item.key}>
                                                <div className="mb-1 flex items-center justify-between text-xs text-[#625E74]">
                                                    <span>{item.value}</span>
                                                    <span>{item.label}</span>
                                                </div>
                                                <input
                                                    type="range"
                                                    min={0}
                                                    max={100}
                                                    value={item.value}
                                                    readOnly
                                                    className="h-1.5 w-full accent-[#2563EB]"
                                                />
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="mt-4 rounded-xl border border-[#E5E7EB] bg-white p-3">
                                <label className="mb-1 block text-right text-xs text-[#625E74]">ملاحظات</label>
                                <textarea
                                    readOnly
                                    value={notesText}
                                    placeholder={notesText ? undefined : 'لا توجد ملاحظات'}
                                    className="h-24 w-full resize-none rounded-md border border-[#E5E7EB] bg-[#FAFAFA] p-2 text-xs text-[#625E74] outline-none"
                                />
                            </div>

                            <div className="mt-5 grid grid-cols-1 gap-2 sm:grid-cols-3">
                                <PrimaryButton
                                    type="button"
                                    className="h-9"
                                    onClick={handleNextInterview}
                                    disabled={!allInterviews?.length}
                                >
                                    استكمال المقابلة التالية
                                </PrimaryButton>
                                <PrimaryButton
                                    type="button"
                                    onClick={() => {
                                        setopenEvaluationDialog(false);
                                        setOpenRejectDialog(true);
                                    }}
                                    className="h-9 bg-[#FCE7E7] text-[#A21515] hover:bg-[#f8dada]"
                                >
                                    رفض
                                </PrimaryButton>
                                <PrimaryButton
                                    type="button"
                                    onClick={() => setopenEvaluationDialog(false)}
                                    className="h-9 border border-[#D0D5DD] bg-transparent text-[#625E74] hover:bg-[#F3F4F6]"
                                >
                                    إلغاء
                                </PrimaryButton>
                            </div>
                        </>
                    )}
                </DialogContent>
            </Dialog>

            <InterviewRejection
                interview={display ? normalizeInterviewFromApi(display) : null}
                openRejectionDialog={openRejectDialog}
                setopenRejectionDialog={setOpenRejectDialog}
            />
        </div>
    );
}
